import React, { useState } from 'react';
import './EstiloPrincipal.css';
import cafeImg from '../imagenes/Deus_Coffee.png'; // Reusing existing image as placeholder
import { useNavigate } from 'react-router-dom';

const MOCK_PRODUCTS = [
    { id: 1, name: 'Café Especial', price: '4.50€', img: cafeImg, category: 'Cafés' },
    { id: 2, name: 'Capuchino', price: '3.50€', img: cafeImg, category: 'Cafés' },
    { id: 3, name: 'Latte Macchiato', price: '3.80€', img: cafeImg, category: 'Cafés' },
    { id: 4, name: 'Espresso', price: '2.00€', img: cafeImg, category: 'Cafés' },
    { id: 5, name: 'Tarta de Queso', price: '4.00€', img: cafeImg, category: 'Postres' },
    { id: 6, name: 'Croissant', price: '2.50€', img: cafeImg, category: 'Desayunos' },
    { id: 7, name: 'Tostada Aguacate', price: '5.50€', img: cafeImg, category: 'Desayunos' },
    { id: 8, name: 'Brownie', price: '3.00€', img: cafeImg, category: 'Postres' },
];

const CATEGORIES = ['Todos', 'Cafés', 'Desayunos', 'Postres'];

function PaginaPrincipal() {
    const navigate = useNavigate();
    const [activeCategory, setActiveCategory] = useState('Todos');

    const handleBack = () => {
        navigate('/');
    };

    const filteredProducts = activeCategory === 'Todos'
        ? MOCK_PRODUCTS
        : MOCK_PRODUCTS.filter(product => product.category === activeCategory);

    return (
        <div className="principal-container">
            <header className="header-principal">
                <button
                    onClick={handleBack}
                    className="btn-back"
                >
                    Volver
                </button>
                <h1 className="header-title">Nuestros Productos</h1>
            </header>

            {/* Category Menu */}
            <nav className="category-menu">
                {CATEGORIES.map(category => (
                    <button
                        key={category}
                        className={`btn-category ${activeCategory === category ? 'active' : ''}`}
                        onClick={() => setActiveCategory(category)}
                    >
                        {category}
                    </button>
                ))}
            </nav>

            <main className="products-grid">
                {filteredProducts.map((product) => (
                    <div key={product.id} className="product-card">
                        <img src={product.img} alt={product.name} className="product-image" />
                        <div className="product-info">
                            <h3 className="product-name">{product.name}</h3>
                            <p className="product-price">{product.price}</p>
                            <button className="btn-buy">Añadir</button>
                        </div>
                    </div>
                ))}
            </main>

            <footer className="footer-principal">
                <div>© IES José Zerpa - Cafetería</div>
            </footer>
        </div>
    );
}

export default PaginaPrincipal;
